const iterations = Number(process.argv[2]);
if (!Number.isSafeInteger(iterations) || iterations <= 0) {
  throw new Error('expected a positive iteration count');
}

for (let i = 0; i < iterations; i++) {
  const child = Bun.spawnSync(['/bin/true']);
  if (child.exitCode !== 0) {
    throw new Error(`child exited with ${child.exitCode}`);
  }
}
